def predict4(I, color):
    tmpl,orig=template_from(I,color)
    H,W=len(I),len(I[0])
    origcells=set((i,j) for i in range(H) for j in range(W) if I[i][j]==color)
    stamped=set()
    changed=True
    while changed:
        changed=False
        for i in range(H):
            for j in range(W):
                if (i,j) in stamped: continue
                cs=[(i+di,j+dj) for di,dj in tmpl]
                if all(0<=a<H and 0<=b<W and (I[a][b]==0 or (a,b) in stamped) and (a,b) not in origcells for a,b in cs):
                    stamped.add((i,j)); changed=True
    out=[row[:] for row in I]
    for (i,j) in stamped:
        for di,dj in tmpl:
            a,b=i+di,j+dj
            if (a,b) not in origcells: out[a][b]=color
    return out,stamped,tmpl,orig

